#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(data.table);library(digest)})
a<-commandArgs(TRUE);project<-normalizePath(if(length(a))a[1]else'paper19opp-revision2');out<-file.path(project,'upr_robustness/specificity');mod<-file.path(project,'upr_robustness/modules');source(file.path(out,'statistics_core.R'));set.seed(2026110614L);B<-4999L
stopifnot(digest(file.path(out,'Hallmark94_descriptive_addendum.txt'),file=TRUE,algo='sha256')=='61292ffd13bb606b0d45d64c2e65801a5d9e5680c69001b4d5fe663ba98fc916')
studies<-c('K562','RPE1','Adamson','Frangieh');files<-c(file.path(mod,'scored',paste0(studies,'_gene_effects.tsv.gz')),file.path(mod,'canonical_Hallmark94',paste0(studies,'_gene_effects.tsv.gz')));fwrite(data.table(file=sub(paste0('^',project,'/'),'',files),sha256=vapply(files,function(f)digest(f,file=TRUE,algo='sha256'),character(1))),file.path(out,'Hallmark94_response_input_hashes.tsv'),sep='\t')
read<-function(folder,axis){rbindlist(lapply(studies,function(st){d<-fread(file.path(folder,paste0(st,'_gene_effects.tsv.gz')));d<-d[d$axis==axis];d[,study:=st];d}),fill=TRUE)}
old<-read(file.path(mod,'scored'),'Hallmark_UPR90');new<-read(file.path(mod,'canonical_Hallmark94'),'Hallmark_UPR94_canonical');panel<-fread(file.path(out,'fixed_target_panels.tsv'));rows<-list();eff<-list();i<-0L
for(cp in unique(panel$comparison))for(mm in c('exact_Lminus_target','fixed_L6780')){
 pp<-panel[comparison==cp];st<-unique(pp$validation_study);ctx<-unique(pp$validation_context);q<-data.table(gene=pp$gene)
 for(def in c('old','new')){d<-if(def=='old')old else new;s<-d[study=='K562'&mode==mm];v<-d[study==st&context==ctx&mode==mm];q[,(paste0('x_',def)):=s$delta_z[match(gene,s$gene)]];q[,(paste0('y_',def)):=v$delta_z[match(gene,v$gene)]]}
 q[,`:=`(comparison=cp,mode=mm)];eff[[length(eff)+1L]]<-copy(q);q<-q[is.finite(x_old)&is.finite(y_old)&is.finite(x_new)&is.finite(y_new)];n<-nrow(q);r0<-sp_rho(q$x_old,q$y_old);r1<-sp_rho(q$x_new,q$y_new);ag<-sp_agreement(q$x_new,q$y_new)
 bs<-vapply(seq_len(B),function(b){j<-sample.int(n,n,replace=TRUE);a<-sp_agreement(q$x_new[j],q$y_new[j]);c(rho90=sp_rho(q$x_old[j],q$y_old[j]),rho94=sp_rho(q$x_new[j],q$y_new[j]),difference=sp_rho(q$x_new[j],q$y_new[j])-sp_rho(q$x_old[j],q$y_old[j]),direction=unname(a['concordance']),kappa=unname(a['kappa']),MCC=unname(a['MCC']))},numeric(6));point<-c(rho90=r0,rho94=r1,difference=r1-r0,direction=unname(ag['concordance']),kappa=unname(ag['kappa']),MCC=unname(ag['MCC']))
 for(metric in names(point)){i<-i+1L;ci<-sp_ci(bs[metric,]);rows[[i]]<-data.table(comparison=cp,mode=mm,metric=metric,estimate=point[metric],gene_bootstrap_low=ci[1],gene_bootstrap_high=ci[2],fixed_target_genes=nrow(pp),paired_genes=n,source94_positive=sum(q$x_new>0),validation94_positive=sum(q$y_new>0),finite_bootstrap_draws=sum(is.finite(bs[metric,])),scope='descriptive identifier robustness; no new P value or ranking')}
}
fwrite(rbindlist(rows),file.path(out,'Hallmark94_identifier_sensitivity.tsv'),sep='\t');fwrite(rbindlist(eff),file.path(out,'Hallmark90_94_paired_gene_effects.tsv.gz'),sep='\t');writeLines(capture.output(sessionInfo()),file.path(out,'Hallmark94_session_info.txt'));print(rbindlist(rows)[metric%in%c('rho90','rho94','difference')])
